import unittest
from solution import add

class T(unittest.TestCase):
    def test_ints(self):
        self.assertEqual(add(2, 3), 5)
    def test_neg(self):
        self.assertEqual(add(-4, 10), 6)
    def test_floats(self):
        self.assertAlmostEqual(add(0.5, 0.25), 0.75)
    def test_zero(self):
        self.assertEqual(add(0, 0), 0)
